import { sql } from "drizzle-orm";
import { check, integer, timestamp, uuid, type PgColumn } from "drizzle-orm/pg-core";

// Conventions every application table follows (FLOW-24, ADR-04):
// - UUID primary keys generated by the database.
// - Audit columns on every row. created_by/updated_by hold the acting user's id;
//   they stay nullable and unconstrained until the users table exists (FLOW-36/37).
// - Soft delete through archived_at; rows are never hard-deleted by the API.
// - Money is stored as integer cents (use moneyCents), never floats.
// - Every time is timestamptz (use timestamptz); display conversion happens in the app.
// - RLS is enabled on every table with `.enableRLS()` and no browser-facing policies;
//   the browser never queries the database directly.
// - Every enum-like text column (`text(name, { enum })`) gets a CHECK constraint
//   with oneOf() (FLOW-187), so the database rejects values the code doesn't know.

export const timestamptz = (name: string) =>
  timestamp(name, { withTimezone: true, mode: "date" });

export const moneyCents = (name: string) => integer(name);

export function baseColumns() {
  return {
    id: uuid("id").primaryKey().defaultRandom(),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    updatedAt: timestamptz("updated_at")
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
    createdBy: uuid("created_by"),
    updatedBy: uuid("updated_by"),
    archivedAt: timestamptz("archived_at"),
  };
}

// CHECK that an enum-like text column holds one of its enum values (FLOW-187).
// Pass the same list the column's `enum` uses. NULL passes a CHECK, so nullable
// columns stay nullable. Values are inlined: drizzle-kit cannot write query
// parameters into a constraint.
export function oneOf(name: string, column: PgColumn, values: readonly string[]) {
  const list = values.map((value) => `'${value.replaceAll("'", "''")}'`).join(", ");
  return check(name, sql`${column} in (${sql.raw(list)})`);
}
